    for (const r of rows) { const l = state.catalog.layers.find(x => x.id === r.id), t = idx.get(r.id), theme = t?.theme || OTHER_THEME; if (!groups.has(theme)) groups.set(theme, []); groups.get(theme).push({ ...r, l, label: t?.name || l?.name || r.name || r.id, status: l?.status || r.collection_status || '' }) }
