        return `<details class="result-theme" open><summary><input type="checkbox" data-clip-theme title="Afficher tout le thème dans la zone" ${on && on === list.length ? 'checked' : ''}><span>${esc(t)}</span><small>${fmt(list.length)}</small></summary>${list.map(r => `<div class="result-row"><input type="checkbox" data-clip-layer="${esc(r.id)}" title="Afficher dans la zone analysée uniquement" ${r.l?.map_count ? '' : 'disabled'} ${state.clip.has(r.id) ? 'checked' : ''}><button type="button" data-context-layer="${esc(r.id)}"><b>${fmt(r.count)}</b>${esc(r.label)}<br><span class="badge ${r.status === 'PARTIAL' ? 'partial' : ''}">${esc(statusName(r.status))}</span></button></div>`).join('')}</details>`
