    document.querySelectorAll('#detail [data-context-layer]').forEach(b => b.onclick = () => { const l = layerOf(b.dataset.contextLayer); if (!l) return; sourceDetail(l); if (state.showResults) { const back = document.createElement('button'); back.className = 'action'; back.textContent = '← Retour au diagnostic'; back.onclick = state.showResults; $('detail').append(back) } });
    const show = async (input, yes) => { const l = layerOf(input.dataset.clipLayer); if (!l || input.disabled) return; input.checked = yes; try { await clipToggle(l, yes) } catch (e) { toast(e.message); input.checked = false; removeClip(l.id) } };
