        for (const id of ['search', 'category', 'origin', 'status', 'active-only']) $(id).addEventListener('input', renderLayers); $('close-dialog').onclick = () => $('source-dialog').close(); $('mobile-filters').onclick = () => $('sidebar').classList.toggle('open'); $('clear').onclick = () => { for (const id of [...state.active]) { const l = state.catalog.layers.find(l => l.id === id); if (l) toggle(l, false); else state.active.delete(id) } renderLayers(); saveView() }; $('reset').onclick = async () => { for (const c of state.loading.values()) c.abort?.(); state.loading.clear(); for (const sids of state.sources.values()) for (const sid of sids) { for (const end of ['-fill', '-line', '-point']) if (state.map?.getLayer(sid + end)) state.map.removeLayer(sid + end); if (state.map?.getSource(sid)) state.map.removeSource(sid) } state.sources.clear(); state.active.clear(); for (const l of state.catalog.layers) delete l._viewKey; $('activity').textContent = 'Aucune couche affichée'; for (const [g, sel] of initialSelections) g.selection = JSON.parse(sel); for (const id of ['search', 'commune']) $(id).value = ''; $('commune').dispatchEvent(new Event('input')); for (const id of ['category', 'origin', 'status']) $(id).value = ''; $('active-only').checked = false; closeDetail(); state.popup?.remove?.(); if (state.analysis) $('analyse').click(); state.selectedZone = null; setClipZone(null); state.showResults = null; state.map?.getSource('analysis-zone')?.setData({ type: 'FeatureCollection', features: [] }); $('home').click(); renderLayers(); saveView() };
